/**
 * A hand-authored index of the public API surface, grouped by area, for the `/docs/api` reference.
 *
 * @remarks
 * This is a curated reference of the load-bearing exports — accurate signatures + one-line
 * descriptions drawn from the TSDoc — the at-a-glance index a consumer scans first. The exhaustive
 * counterpart is **TypeDoc** over the same core TSDoc, generated by `pnpm docs:api` in the engine
 * repository; `DocsApiPage` points readers there.
 *
 * @packageDocumentation
 */

/** One documented export. */
export interface ApiEntry {
	/** One-line description. */
	readonly description: string;
	/** Exported name. */
	readonly name: string;
	/** Signature (or shape). */
	readonly signature: string;
}

/** A group of related exports. */
export interface ApiGroup {
	/** What this group is for. */
	readonly blurb: string;
	/** The exports. */
	readonly entries: readonly ApiEntry[];
	/** Where they come from, e.g. `@filter-enginez/core`. */
	readonly from: string;
	/** Group title. */
	readonly title: string;
}

